tt=TextToPath()
def fontsize(style):return float(re.search(r'([\d.]+)px',style['font']).group(1))
def fontstyle(style):return {'italic':'italic' in style['font'],'bold':bool(re.search(r'\b700\b',style['font']))}
def decoded_char(c, style):
    # Matplotlib's legacy cmsy10 encodes proportional-to at the slash slot.
    # Resolve this observed fixture glyph to Unicode rather than changing meaning.
    if 'cmsy10' in style['font']:
        if c != '/':raise ValueError('Unsupported cmsy10 fixture glyph')
        return '\u221d', 'Cambria Math'
